import { describe, expect, it, vi } from "vitest";
import type Anthropic from "@anthropic-ai/sdk";
import { MemoryStore } from "@/lib/store/memory";
import {
  COMPACT_AT_TOKENS,
  COMPACTION_BETA,
  buildCompactionParams,
  compactionUsage,
  estimateTokens,
  findCut,
  hasCompactionBlock,
  isCleanBoundary,
  maybeCompact,
